// Source-based station interiors and unit information. Missing hours stay unknown.
let placeInfo=null;
const hallPlans={},unifiedRenderer=render;
const hallMatrix=n=>{const x=n===1?226.33:264.23,y=n===1?175.88:550.23,w=n===1?480:406.58,h=n===1?313.29:230.17;const a=13.02/w,b=-65.13/w,c=40.87/h,d=8.08/h;return [a,b,c,d,537.56-a*x-c*y,384.55-b*x-d*y]};
const hallPoint=(n,x,y)=>{const [a,b,c,d,e,f]=hallMatrix(n);return [a*x+c*y+e,b*x+d*y+f]};
function cameraHall(){zoom=7;pan=[(525-564)*zoom,(360-354)*zoom]}
function addText(parent,tag,text,cls){const e=document.createElement(tag);e.textContent=text;if(cls)e.className=cls;parent.append(e);return e}
function sourceLink(parent,label,url){const a=addText(parent,'a',label,'place-source');a.href=url;a.target='_blank';a.rel='noopener';return a}
function placeCard(id){if(!placeInfo)return;const box=$('#mall-selection');box.replaceChildren();const special=placeInfo.stores[id],station=id.startsWith('pkp-');const name=special?.name||unitName(id);addText(box,'strong',name,'place-name');addText(box,'div',(station?(english?'Railway station':'Dworzec kolejowy'):'Avenida')+' · '+floorName(mallFloorOf(id)),'place-floor');
if(name.startsWith('Wkrótce')){addText(box,'p',english?'The official plan marks this unit as opening soon.':'Oficjalny plan oznacza ten lokal jako „wkrótce otwarcie”.','place-note');sourceLink(box,english?'Official unit status ↗':'Status na oficjalnym planie ↗','https://www.avenidapoznan.com/o-centrum/plan-centrum/?location='+encodeURIComponent(id));return;}
const weekly=special?.weekly;addText(box,'h3',english?'Opening hours':'Godziny otwarcia');
if(weekly){const days=english?['Mon','Tue','Wed','Thu','Fri','Sat','Sun']:['Pon.','Wt.','Śr.','Czw.','Pt.','Sob.','Niedz.'];const table=document.createElement('table');table.className='hours-table';for(let i=0;i<7;i++){const day=(i+1)%7,row=table.insertRow();const th=document.createElement('th');th.scope='row';th.textContent=days[i];row.append(th);row.insertCell().textContent=weekly[day]||(english?'Not confirmed':'Niepotwierdzone')}box.append(table);addText(box,'p',english?'Regular schedule. Holiday exceptions may apply.':'Standardowy harmonogram. W święta mogą obowiązywać wyjątki.','place-note');sourceLink(box,english?'Hours source ↗':'Źródło godzin ↗',special.source);addText(box,'small',(english?'Checked: ':'Sprawdzono: ')+placeInfo.checkedAt);}
else{addText(box,'p',english?'Individual opening hours have not been confirmed.':'Godziny tego lokalu nie są jeszcze potwierdzone.','unknown-hours');if(!station){const dl=document.createElement('details');const sm=addText(dl,'summary',english?'Centre hours (not this unit’s schedule)':'Godziny centrum — nie harmonogram lokalu');addText(dl,'p',english?'Mon–Sat 09:00–21:00. Sundays and holidays: check the official calendar. Individual units may differ.':'Pon.–sob. 09:00–21:00. Niedziele i święta: sprawdź kalendarz centrum. Poszczególne lokale mogą działać inaczej.');sourceLink(dl,english?'Centre calendar ↗':'Kalendarz centrum ↗',placeInfo.centre.source);box.append(dl)}}
if(station){addText(box,'p',english?'Location follows the plan linked by PKP. Geographic alignment is approximate; the plan’s last update is not stated.':'Położenie według planu podlinkowanego przez PKP. Dopasowanie geograficzne jest przybliżone; data ostatniej aktualizacji planu nie jest podana.','place-note');sourceLink(box,english?'Station floor plan ↗':'Plan hali i antresoli ↗',placeInfo.stationPlan.source);}else sourceLink(box,english?'Location on official mall plan ↗':'Lokal na oficjalnym planie ↗','https://www.avenidapoznan.com/o-centrum/plan-centrum/?location='+encodeURIComponent(id));if(special?.note)addText(box,'p',special.note,'place-note');if(special?.locationNote)addText(box,'p',special.locationNote,'place-note');}
selectMall=function(id){mallSelected=id;level=mallFloorOf(id);if(id.startsWith('pkp-'))cameraHall();else cameraMall();render();placeCard(id);$('#mall-selection').scrollIntoView({block:'nearest',behavior:'smooth'})};
render=function(){unifiedRenderer();if(placeInfo&&(level===1||level===2)&&hallPlans[level]){const root=svg.querySelector(':scope > g');for(const oldLabel of root.querySelectorAll('text'))if(zoom>3||/HALA DWORCA|STATION HALL/.test(oldLabel.textContent))oldLabel.setAttribute('visibility','hidden');const wrapper=document.createElementNS('http://www.w3.org/2000/svg','g');wrapper.setAttribute('class','station-interior');wrapper.setAttribute('transform','matrix('+hallMatrix(level).join(' ')+')');wrapper.innerHTML=hallPlans[level];root.append(wrapper);for(const unit of placeInfo.stationPlan.units.filter(u=>u.level===level)){const [x,y,w,h]=unit.rect;const sourceShape=[...wrapper.querySelectorAll('path[data-bounds]')].find(p=>p.getAttribute('data-bounds').split(',').every((v,i)=>Math.abs(+v-unit.rect[i])<.1));const r=sourceShape?sourceShape.cloneNode(false):document.createElementNS('http://www.w3.org/2000/svg','rect');if(!sourceShape){r.setAttribute('x',x);r.setAttribute('y',y);r.setAttribute('width',w);r.setAttribute('height',h);}r.dataset.shop=unit.id;r.setAttribute('class','station-unit'+(mallSelected===unit.id?' selected':''));r.setAttribute('role','button');r.setAttribute('aria-label',unit.name);r.setAttribute('tabindex','0');const title=document.createElementNS('http://www.w3.org/2000/svg','title');title.textContent=unit.name;r.append(title);r.onclick=()=>selectMall(unit.id);r.onkeydown=e=>{if(e.key==='Enter'||e.key===' '){e.preventDefault();selectMall(unit.id)}};wrapper.append(r);const p=hallPoint(level,x+w/2,y+h/2);if(zoom>2&&(['pkp-03','pkp-04','pkp-05','pkp-06','pkp-07','pkp-10','pkp-11'].includes(unit.id)||mallSelected===unit.id)){const label=unit.name.split(' · ')[0].replace(' · dworzec','');root.insertAdjacentHTML('beforeend',txt(p[0],p[1],label,1.6,'#e8f2d4','text-anchor="middle" paint-order="stroke" stroke="#20352a" stroke-width=".45"'));}}const services=level===1?[[340,250,'Kasy'],[290,200,'WC'],[429,265,'↕'],[556,265,'↕'],[680,265,'↕'],[610,421,'↕']]:[[610,802,'↕']];if(zoom>2)for(const [sx,sy,label] of services){const sp=hallPoint(level,sx,sy);root.insertAdjacentHTML('beforeend',txt(sp[0],sp[1],label,1.7,'#d5e8c5','text-anchor="middle"'));}root.insertAdjacentHTML('beforeend',txt(595,323,english?'STATION · PKP PLAN':'DWORZEC · PLAN PKP',3,'#c6cba2','text-anchor="middle"'));}
if(mallSelected)placeCard(mallSelected);};
$('#focus-hall').onclick=()=>{if(level!==1&&level!==2)level=1;cameraHall();render()};
async function loadPlaces(){try{const [meta,...plans]=await Promise.all([fetch('store-info.json'),fetch('station/level-1.svg'),fetch('station/level-2.svg')]);if(!meta.ok||plans.some(r=>!r.ok))throw Error('Missing station data');placeInfo=await meta.json();for(let i=0;i<2;i++){const raw=await plans[i].text(),doc=new DOMParser().parseFromString(raw,'image/svg+xml');if(doc.querySelector('parsererror'))throw Error('Invalid plan');hallPlans[i+1]=doc.documentElement.innerHTML;}for(const u of placeInfo.stationPlan.units){mallNames[u.id]=u.name;stationUnitLevels[u.id]=u.level;}render()}catch(e){$('#mall-selection').textContent=english?'Station interior data could not load. Refresh to retry.':'Nie udało się wczytać wnętrza dworca. Odśwież stronę.'}}
loadPlaces();
